def min_cost_to_illuminate(n, m, k, blocked, costs):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    blocked_set = set(blocked)

    for i in range(1, n + 1):
        if i in blocked_set:
            continue
        for j in range(1, min(i, k) + 1):
            dp[i] = min(dp[i], dp[i - j] + costs[j - 1])

    return dp[n] if dp[n] != float('inf') else -1

